'use client'

import type { ComponentProps } from 'react'
import {
  createTimelineController,
  Timeline as UiTimeline,
  TimelineConnector as UiTimelineConnector,
  TimelineDescription as UiTimelineDescription,
  TimelineItem as UiTimelineItem,
  TimelineMarker as UiTimelineMarker,
  TimelineTime as UiTimelineTime,
  TimelineTitle as UiTimelineTitle,
} from '@ui-sdk/react/timeline'

import './timeline.css'

function omit<T extends object, const K extends readonly (keyof T)[]>(
  obj: T,
  ...keys: K
): Omit<T, K[number]> {
  const copy = { ...obj }
  for (const key of keys) delete copy[key]
  return copy
}

export { createTimelineController }
export type {
  TimelineController,
  TimelineOrientation,
  TimelineState,
  TimelineStatus,
} from '@ui-sdk/react/timeline'

type UiTimelineProps = ComponentProps<typeof UiTimeline>

export type TimelineProps = Omit<UiTimelineProps, 'className' | 'render'> & {
  className?: UiTimelineProps['className']
  render?: UiTimelineProps['render']
}

export function Timeline(props: TimelineProps) {
  const rest = omit(props, 'className', 'render')

  return <UiTimeline {...rest} className={props.className} render={props.render} />
}

